-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

create table public.copyright_notices (
  id uuid default gen_random_uuid() not null,
  claimant_name text not null,
  claimant_email text not null,
  claimant_address text not null,
  claimant_phone text,
  rights_holder text,
  work_description text not null,
  content_urls text[] not null,
  good_faith boolean not null,
  accurate_and_authorised boolean not null,
  signature text not null,
  submitted_by uuid,
  status text default 'received'::text not null,
  resolved_by uuid,
  resolved_at timestamp with time zone,
  resolution_note text,
  takedown jsonb,
  created_at timestamp with time zone default now() not null
);

alter table public.copyright_notices enable row level security;

-- Comments
comment on table public.copyright_notices is 'Copyright notices filed from /copyright (R69-dmca). Server-written; admins read and act. Holds the claimant''s contact details: never public.';

-- Constraints
alter table public.copyright_notices add constraint copyright_notices_accurate_and_authorised_check CHECK (accurate_and_authorised);
alter table public.copyright_notices add constraint copyright_notices_claimant_address_check CHECK (length(btrim(claimant_address)) >= 5 AND length(btrim(claimant_address)) <= 1000);
alter table public.copyright_notices add constraint copyright_notices_claimant_email_check CHECK (length(claimant_email) <= 320 AND claimant_email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'::text);
alter table public.copyright_notices add constraint copyright_notices_claimant_name_check CHECK (length(btrim(claimant_name)) >= 2 AND length(btrim(claimant_name)) <= 200);
alter table public.copyright_notices add constraint copyright_notices_claimant_phone_check CHECK (claimant_phone IS NULL OR length(claimant_phone) <= 50);
alter table public.copyright_notices add constraint copyright_notices_content_urls_check CHECK (cardinality(content_urls) >= 1 AND cardinality(content_urls) <= 20);
alter table public.copyright_notices add constraint copyright_notices_good_faith_check CHECK (good_faith);
alter table public.copyright_notices add constraint copyright_notices_pkey PRIMARY KEY (id);
alter table public.copyright_notices add constraint copyright_notices_resolved_by_fkey FOREIGN KEY (resolved_by) REFERENCES public.profiles(id) ON DELETE SET NULL;
alter table public.copyright_notices add constraint copyright_notices_rights_holder_check CHECK (rights_holder IS NULL OR length(rights_holder) <= 200);
alter table public.copyright_notices add constraint copyright_notices_signature_check CHECK (length(btrim(signature)) >= 2 AND length(btrim(signature)) <= 200);
alter table public.copyright_notices add constraint copyright_notices_status_check CHECK (status = ANY (ARRAY['received'::text, 'actioned'::text, 'rejected'::text]));
alter table public.copyright_notices add constraint copyright_notices_submitted_by_fkey FOREIGN KEY (submitted_by) REFERENCES auth.users(id) ON DELETE SET NULL;
alter table public.copyright_notices add constraint copyright_notices_work_description_check CHECK (length(btrim(work_description)) >= 10 AND length(btrim(work_description)) <= 4000);

-- Indexes
CREATE INDEX copyright_notices_open_idx ON public.copyright_notices USING btree (created_at) WHERE (status = 'received'::text);
CREATE INDEX copyright_notices_resolved_by_idx ON public.copyright_notices USING btree (resolved_by);
CREATE INDEX copyright_notices_submitted_by_idx ON public.copyright_notices USING btree (submitted_by);

-- Grants
grant select on table public.copyright_notices to authenticated;
grant all on table public.copyright_notices to service_role;
